cardCss:
.sp-root{ background:#f7f9fc; border:1px solid #e2e8f0; border-radius:14px; box-shadow:0 1px 3px rgba(30,41,59,.06); margin-bottom:16px; overflow:hidden; }
.sp-bar{ display:flex; align-items:center; justify-content:space-between; gap:12px; padding:10px 16px; border-bottom:1px solid #e9eef4; background:#eef2f7; }
.sp-bar-left{ display:inline-flex; align-items:center; gap:8px; min-width:0; }
.sp-badge{ display:inline-flex; align-items:center; font-size:11px; font-weight:700; letter-spacing:.5px; padding:3px 9px; border-radius:9999px; color:#fff; white-space:nowrap; }
.sp-label{ font-size:13px; font-weight:600; color:#33415c; }
.sp-actions{ display:flex; gap:7px; }
.sp-act{ position:relative; width:44px; height:44px; border-radius:9999px; border:none; cursor:pointer; background:#e2e9f1; color:#5a6b7d; font-size:17px; display:inline-flex; align-items:center; justify-content:center; transition:all .18s ease; }
.sp-act:hover{ background:#3b82f6; color:#fff; }
.sp-act:active{ transform:scale(.92); }
.sp-act.is-active{ background:#3b82f6; color:#fff; }
.sp-act.act-mark.is-active{ background:#f59e0b; color:#fff; }
.sp-act.act-fav.is-active{ background:#ec4899; color:#fff; }
.sp-act::after{ content:attr(data-tip); position:absolute; top:100%; left:50%; transform:translateX(-50%) translateY(3px); background:#33415c; color:#fff; font-size:11.5px; font-weight:600; padding:4px 9px; border-radius:7px; white-space:nowrap; opacity:0; visibility:hidden; pointer-events:none; z-index:20; transition:opacity .18s ease, transform .18s ease, visibility .18s; }
.sp-act:hover::after{ opacity:1; visibility:visible; transform:translateX(-50%) translateY(7px); }
.sp-body{ padding:20px 22px; display:flex; flex-direction:column; }
.sp-tok{ padding:0 2px; border-radius:3px; font-weight:700; border-bottom:3px solid transparent; }
.sp-sentence{ font-size:34px; font-weight:800; color:#1e293b; line-height:1.4; letter-spacing:-.4px; margin-bottom:14px; }
.sp-formula-row{ display:flex; align-items:center; gap:12px; flex-wrap:wrap; margin-bottom:6px; }
.sp-formula{ display:inline-flex; align-items:center; gap:5px; flex-wrap:wrap; }
.sp-part{ font-size:21px; font-weight:800; padding:5px 12px; border-radius:8px; color:#fff; }
.sp-plus{ font-size:21px; font-weight:700; color:#cbd5e1; }
.sp-name{ font-size:26px; font-weight:800; color:#1e293b; }
.sp-name-en{ font-size:14px; color:#94a3b8; margin-bottom:14px; letter-spacing:.3px; }
.sp-sec{ font-size:11px; font-weight:700; letter-spacing:1.2px; text-transform:uppercase; color:#94a3b8; margin-bottom:7px; }
.sp-breakdown{ display:flex; flex-direction:column; gap:5px; margin-bottom:14px; }
.sp-row{ display:flex; align-items:center; gap:9px; font-size:15px; }
.sp-dot{ width:10px; height:10px; border-radius:50%; flex:0 0 auto; }
.sp-role{ font-size:12.5px; color:#64748b; }
.sp-note{ font-size:14px; color:#475569; line-height:1.65; background:#eef2f7; border-left:3px solid #3b82f6; border-radius:0 8px 8px 0; padding:9px 12px; }
.sp-note-en{ font-size:14px; color:#475569; line-height:1.65; background:#f3f0fa; border-left:3px solid #8b5cf6; border-radius:0 8px 8px 0; padding:9px 12px; font-style:italic; }
.sp-note + .sp-note-en{ margin-top:8px; }
.sp-trans{ margin-top:12px; font-size:14px; color:#64748b; }
.sp-trans b{ color:#475569; }
.sp-example{ font-size:22px; font-weight:700; color:#1e293b; line-height:1.5; margin-bottom:12px; }
.sp-contrast{ display:flex; flex-direction:column; gap:16px; }
.sp-c-item{ }
.sp-c-tag{ display:inline-block; font-size:10.5px; font-weight:700; letter-spacing:.5px; color:#94a3b8; margin-bottom:5px; }
.sp-c-sentence{ font-size:21px; font-weight:800; color:#1e293b; line-height:1.45; letter-spacing:-.2px; margin-bottom:6px; }
.sp-divider{ height:1px; background:#e9eef4; margin:6px 0; }
.sp-overview{ display:flex; flex-direction:column; margin-bottom:14px; }
.sp-ov-item{ display:flex; align-items:flex-start; gap:11px; padding:8px 0; }
.sp-ov-item + .sp-ov-item{ border-top:1px dashed #e9eef4; }
.sp-ov-num{ flex:0 0 auto; width:22px; height:22px; border-radius:50%; background:#e2e9f1; color:#5a6b7d; font-size:12px; font-weight:700; display:flex; align-items:center; justify-content:center; margin-top:4px; }
.sp-ov-body{ flex:1; min-width:0; }
.sp-ov-head{ display:flex; align-items:center; gap:10px; flex-wrap:wrap; margin-bottom:3px; }
.sp-overview .sp-part{ font-size:14px; padding:3px 8px; }
.sp-overview .sp-plus{ font-size:14px; }
.sp-ov-name{ font-size:15px; font-weight:700; color:#1e293b; }
.sp-ov-sentence{ font-size:13.5px; color:#64748b; }

.sp-rule{ font-size:14px; color:#2f5a5e; line-height:1.7; background:#eef7f7; border-left:3px solid #14b8a6; border-radius:0 8px 8px 0; padding:9px 13px; margin-bottom:14px; }
.sp-rule b{ color:#0d9488; }
.sp-checks{ display:flex; flex-direction:column; gap:10px; margin-bottom:14px; }
.sp-check{ background:#fbfcfd; border:1px solid #e4eaf1; border-radius:10px; padding:10px 13px; }
.sp-chk-top{ display:flex; align-items:center; gap:8px; flex-wrap:wrap; margin-bottom:7px; }
.sp-chk-before{ font-size:16px; font-weight:700; color:#64748b; }
.sp-chk-arrow{ font-size:11px; font-weight:700; color:#0d9488; background:#e6f4f3; border-radius:6px; padding:2px 7px; white-space:nowrap; }
.sp-chk-after{ font-size:17px; font-weight:800; color:#1e293b; }
.sp-chk-mark{ font-size:11.5px; font-weight:700; padding:3px 8px; border-radius:9999px; color:#fff; background:#33415c; white-space:nowrap; }
.sp-chk-mark.no{ background:#94a3b8; }
.sp-chk-verdict{ display:flex; align-items:center; gap:8px; flex-wrap:wrap; font-size:13px; color:#475569; }
.sp-check .sp-part{ font-size:13px; padding:3px 8px; }
.sp-check .sp-plus{ font-size:13px; }
.sp-chk-name{ font-weight:800; font-size:15px; color:#1e293b; }
.sp-chk-why{ color:#64748b; font-size:12.5px; }
/* dark mode */
/* dark mode */
body.dark-mode .sp-root{ background:#1f262a; border-color:#2e363b; }
body.dark-mode .sp-bar{ background:#232b30; border-bottom-color:#2e363b; }
body.dark-mode .sp-label, body.dark-mode .sp-name, body.dark-mode .sp-sentence, body.dark-mode .sp-c-sentence, body.dark-mode .sp-example{ color:#e2e8f0; }
body.dark-mode .sp-note{ background:#252e33; color:#a3b5b4; }
body.dark-mode .sp-note-en{ background:#2a2633; color:#b8adcc; }
body.dark-mode .sp-trans, body.dark-mode .sp-role, body.dark-mode .sp-name-en, body.dark-mode .sp-sec, body.dark-mode .sp-c-tag{ color:#7d8f8e; }
body.dark-mode .sp-act{ background:#2b343a; color:#a3b5b4; }
body.dark-mode .sp-act:hover{ background:#3b82f6; color:#fff; }
body.dark-mode .sp-plus{ color:#475569; }
body.dark-mode .sp-divider{ background:#2e363b; }
body.dark-mode .sp-ov-item + .sp-ov-item{ border-top-color:#2e363b; }
body.dark-mode .sp-ov-num{ background:#2b343a; color:#a3b5b4; }
body.dark-mode .sp-ov-name{ color:#e2e8f0; }
body.dark-mode .sp-ov-sentence{ color:#7d8f8e; }
body.dark-mode .sp-rule{ background:#1e2c2c; color:#9fc6c4; }
body.dark-mode .sp-check{ background:#232b30; border-color:#2e363b; }
body.dark-mode .sp-chk-before{ color:#7d8f8e; }
body.dark-mode .sp-chk-arrow{ background:#24393a; color:#5eead4; }
body.dark-mode .sp-chk-after, body.dark-mode .sp-chk-name{ color:#e2e8f0; }
body.dark-mode .sp-chk-why{ color:#7d8f8e; }
body.dark-mode .sp-chk-mark{ background:#3d4a58; }
body.dark-mode .sp-chk-mark.no{ background:#64748b; }

cardJs:
(function () {
  'use strict';
  function esc(s){ if(s==null) return ''; return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
  var ROLE = {
    'S':    { c:'#3b82f6', n:'主语' },
    'V':    { c:'#22c55e', n:'谓语' },
    'P':    { c:'#8b5cf6', n:'表语' },
    'O':    { c:'#f59e0b', n:'宾语' },
    'IO':   { c:'#fbbf24', n:'间接宾语' },
    'DO':   { c:'#f59e0b', n:'直接宾语' },
    'OC':   { c:'#ec4899', n:'宾补' },
    'A':    { c:'#94a3b8', n:'状语' },
    'Attr': { c:'#94a3b8', n:'定语' }
  };
  var BADGE = {
    'overview':  { c:'#0ea5e9', t:'总览' },
    'pattern':   { c:'#3b82f6', t:'句型' },
    'component': { c:'#22c55e', t:'成分' },
    'contrast':  { c:'#8b5cf6', t:'辨析' },
    'check':     { c:'#e11d48', t:'检验' }
  };
  function rl(r){ return ROLE[r] || { c:'#64748b', n:'' }; }
  function tok(t){ var r=rl(t.role); return '<span class="sp-tok" style="color:'+r.c+';border-bottom-color:'+r.c+'">'+esc(t.text)+'</span>'; }
  function sentence(bd, cls){
    if(!bd || !bd.length) return '';
    var parts=[]; for(var i=0;i<bd.length;i++) parts.push(tok(bd[i]));
    return '<span class="'+cls+'">'+parts.join(' ')+'</span>';
  }
  function formula(p){
    if(!p) return '';
    var toks=p.split('+'); var out='';
    for(var i=0;i<toks.length;i++){
      var t=toks[i].trim(); var r=ROLE[t];
      out += r ? '<span class="sp-part" style="background:'+r.c+'">'+esc(t)+'</span>'
               : '<span class="sp-plus">'+esc(t)+'</span>';
    }
    return out;
  }
  function breakdown(bd){
    if(!bd || !bd.length) return '';
    var out='';
    for(var i=0;i<bd.length;i++){
      var r=rl(bd[i].role);
      out += '<div class="sp-row"><span class="sp-dot" style="background:'+r.c+'"></span>'
           + '<span class="sp-tok" style="color:'+r.c+';border-bottom-color:'+r.c+'">'+esc(bd[i].text)+'</span>'
           + '<span class="sp-role">'+esc(r.n)+'</span></div>';
    }
    return out;
  }
  function actionBar(){
    return '<div class="sp-actions">'
      + '<button class="sp-act act-audio" data-action="audio" data-tip="朗读"><i class="fa-solid fa-volume-high"></i></button>'
      + '<button class="sp-act act-mark" data-action="mark" data-tip="标记"><i class="fa-regular fa-star"></i></button>'
      + '<button class="sp-act act-fav" data-action="favorite" data-tip="收藏"><i class="fa-regular fa-bookmark"></i></button>'
      + '</div>';
  }
  window.cardTemplate = {
    name: '英语句子成分与五种基本句型',
    fields: [
      { key:'type',       label:'类型',       hideable:false },
      { key:'rows',       label:'句型列表',   hideable:false },
      { key:'labelZh',    label:'中文名',     hideable:false },
      { key:'labelEn',    label:'英文名',     hideable:true  },
      { key:'pattern',    label:'句型公式',   hideable:false },
      { key:'pattern2',   label:'句型公式2',  hideable:true  },
      { key:'sentence',   label:'例句',       hideable:false },
      { key:'breakdown',  label:'成分拆解',   hideable:false },
      { key:'sentence2',  label:'对比例句',   hideable:true  },
      { key:'breakdown2', label:'对比拆解',   hideable:true  },
      { key:'sentenceZh', label:'中文释义',   hideable:true  },
      { key:'note',       label:'讲解',       hideable:true  },
      { key:'noteEn',     label:'英文解释',   hideable:true  },
      { key:'rule',       label:'检验规则',   hideable:false },
      { key:'checks',     label:'检验示例',   hideable:false }
    ],
    render: function (cardHtml, cardData, api) {
      var data = (api && api.getCardData) ? api.getCardData() : cardData;
      var d = data.data || {};
      var hidden = (api.getHiddenFields && api.getHiddenFields()) || {};
      function h(k, html){ return (hidden.has && hidden.has(k)) ? '' : html; }
      var b = BADGE[d.type] || { c:'#64748b', t:'' };
      var body = '';
      if (d.type === 'overview') {
        var rows = d.rows || [];
        var ovHtml = '';
        for (var i=0;i<rows.length;i++){
          var r = rows[i] || {};
          ovHtml += '<div class="sp-ov-item"><span class="sp-ov-num">'+(i+1)+'</span>'
                  + '<div class="sp-ov-body">'
                  +   '<div class="sp-ov-head"><span class="sp-formula">'+formula(r.pattern)+'</span>'
                  +   '<span class="sp-ov-name">'+esc(r.labelZh)+'</span></div>'
                  +   '<div class="sp-ov-sentence">'+esc(r.sentence)+'</div>'
                  + '</div></div>';
        }
        body = '<div class="sp-name" style="font-size:30px">'+esc(d.labelZh)+'</div>'
             + h('labelEn', '<div class="sp-name-en" style="font-size:15px">'+esc(d.labelEn)+'</div>')
             + '<div class="sp-overview">'+ovHtml+'</div>'
             + h('note', '<div class="sp-note">'+esc(d.note)+'</div>');
      } else if (d.type === 'component') {
        body = '<div class="sp-name" style="font-size:32px">'+esc(d.labelZh)+'</div>'
             + h('labelEn', '<div class="sp-name-en" style="font-size:15px">'+esc(d.labelEn)+'</div>')
             + h('note', '<div class="sp-note">'+esc(d.note)+'</div>')
             + h('noteEn', '<div class="sp-note-en">'+esc(d.noteEn)+'</div>')
             + '<div class="sp-sec" style="margin-top:16px">Example</div>'
             + h('breakdown', '<div class="sp-example">'+sentence(d.breakdown,'')+'</div>')
             + h('breakdown', '<div class="sp-breakdown">'+breakdown(d.breakdown)+'</div>')
             + h('sentenceZh', '<div class="sp-trans"><b>译：</b>'+esc(d.sentenceZh)+'</div>');
      } else if (d.type === 'contrast') {
        body = '<div class="sp-name" style="font-size:21px">'+esc(d.labelZh)+'</div>'
             + h('labelEn', '<div class="sp-name-en">'+esc(d.labelEn)+'</div>')
             + '<div class="sp-contrast">'
             + '<div class="sp-c-item"><div class="sp-c-tag">句子 A</div>'
             + h('breakdown', '<div class="sp-c-sentence">'+sentence(d.breakdown,'')+'</div>')
             + h('pattern', '<div class="sp-formula">'+formula(d.pattern)+'</div>')
             + h('breakdown', '<div class="sp-breakdown">'+breakdown(d.breakdown)+'</div>')
             + '</div>'
             + '<div class="sp-c-item"><div class="sp-c-tag">句子 B</div>'
             + h('breakdown2', '<div class="sp-c-sentence">'+sentence(d.breakdown2,'')+'</div>')
             + h('pattern2', '<div class="sp-formula">'+formula(d.pattern2)+'</div>')
             + h('breakdown2', '<div class="sp-breakdown">'+breakdown(d.breakdown2)+'</div>')
             + '</div>'
             + '</div>'
             + h('note', '<div class="sp-note" style="margin-top:14px">'+esc(d.note)+'</div>')
             + h('sentenceZh', '<div class="sp-trans"><b>译：</b>'+esc(d.sentenceZh)+'</div>');
      } else if (d.type === 'check') {
        var checks = d.checks || [];
        var chkHtml = '';
        for (var ci=0; ci<checks.length; ci++){
          var ck = checks[ci] || {};
          var mk = ck.ok
            ? '<span class="sp-chk-mark">&#10003; 说得通</span>'
            : '<span class="sp-chk-mark no">&#10007; 说不通</span>';
          chkHtml += '<div class="sp-check">'
              + '<div class="sp-chk-top"><span class="sp-chk-before">'+esc(ck.before)+'</span>'
              + '<span class="sp-chk-arrow">换成 be</span>'
              + '<span class="sp-chk-after">'+esc(ck.after)+'</span>'
              + mk + '</div>'
              + '<div class="sp-chk-verdict"><span class="sp-formula">'+formula(ck.pattern)+'</span>'
              + '<span class="sp-chk-name">'+esc(ck.name)+'</span>'
              + (ck.why ? '<span class="sp-chk-why">'+esc(ck.why)+'</span>' : '')
              + '</div></div>';
        }
        body = '<div class="sp-name" style="font-size:28px">'+esc(d.labelZh)+'</div>'
             + h('labelEn', '<div class="sp-name-en" style="font-size:15px">'+esc(d.labelEn)+'</div>')
             + h('rule', '<div class="sp-rule">'+esc(d.rule)+'</div>')
             + h('checks', '<div class="sp-checks">'+chkHtml+'</div>')
             + h('note', '<div class="sp-note">'+esc(d.note)+'</div>');
      } else { // pattern
        body = h('breakdown', '<div class="sp-sentence">'+sentence(d.breakdown,'')+'</div>')
             + '<div class="sp-formula-row">'
             +   h('pattern', '<div class="sp-formula">'+formula(d.pattern)+'</div>')
             +   '<div class="sp-name">'+esc(d.labelZh)+'</div>'
             + '</div>'
             + h('labelEn', '<div class="sp-name-en">'+esc(d.labelEn)+'</div>')
             + '<div class="sp-sec">成分拆解</div>'
             + h('breakdown', '<div class="sp-breakdown">'+breakdown(d.breakdown)+'</div>')
             + h('note', '<div class="sp-note">'+esc(d.note)+'</div>')
             + h('sentenceZh', '<div class="sp-trans"><b>译：</b>'+esc(d.sentenceZh)+'</div>');
      }
      return '<div class="sp-root" data-card-id="'+esc(data.id)+'">'
           + '<div class="sp-bar">'
           +   '<span class="sp-bar-left"><span class="sp-badge" style="background:'+b.c+'">'+esc(b.t)+'</span>'
           +     h('labelZh', '<span class="sp-label">'+esc(d.labelZh)+'</span>') + '</span>'
           +   actionBar()
           + '</div>'
           + '<div class="sp-body">'+body+'</div>'
           + '</div>';
    },
    init: function (el, cardData, api) {
      var data = (api && api.getCardData) ? api.getCardData() : cardData;
      var d = data.data || {};
      var ab = el.querySelector('.act-audio');
      if (ab) ab.addEventListener('click', function(){ if(api&&api.playAudio) api.playAudio(d.labelZh || ''); if(api&&api.track) api.track('audio_play'); });
      var mb = el.querySelector('.act-mark');
      if (mb) mb.addEventListener('click', function(){ if(api&&api.toggleMark) api.toggleMark(); mb.classList.toggle('is-active'); var i=mb.querySelector('i'); if(i){ i.classList.toggle('fa-regular'); i.classList.toggle('fa-solid'); } if(api&&api.track) api.track('word_mark'); });
      var vb = el.querySelector('.act-fav');
      if (vb) vb.addEventListener('click', function(){ if(api&&api.toggleFavorite) api.toggleFavorite(); vb.classList.toggle('is-active'); var i=vb.querySelector('i'); if(i){ i.classList.toggle('fa-regular'); i.classList.toggle('fa-solid'); } if(api&&api.track) api.track('favorite_toggle'); });
    }
  };
})();
